import { toHex } from "@midnight-ntwrk/midnight-js-utils";

/**
 * Generates a buffer containing a series of randomly generated bytes.
 *
 * @param length The number of bytes to generate.
 * @returns A `Uint8Array` representing `length` randomly generated bytes.
 */
export const randomBytes = (length: number): Uint8Array => {
  const bytes = new Uint8Array(length);
  crypto.getRandomValues(bytes);
  return bytes;
};

/**
 * Generates a random hex-encoded coin public key.
 */
export const randomCoinPublicKeyHex = (): string => {
  return toHex(randomBytes(32));
};

/**
 * Generates a random string suitable for use as a storage ID, label, or provider.
 */
export const randomString = (length = 16): string => {
  return toHex(randomBytes(length));
};

/**
 * Generates a random bigint timestamp (milliseconds since epoch).
 */
export const randomTimestamp = (): bigint => {
  return BigInt(Date.now()) + BigInt(Math.floor(Math.random() * 1_000_000));
};
